"""Beat the Clock: an arithmetic game. One minute of questions from all four operations;
type the answer and press Enter. A Timer counts the seconds down; the best score is kept
with SaveSetting, so it is still there the next time the program runs."""

import random

from vp6 import *

SECONDS = 60
APP, SECTION = "VP6 Lessons", "Beat the Clock"


class Form1(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Beat the Clock'
        self.Width = 480
        self.Height = 360
        self.lblTime = Label(self, Caption='', Left=16, Top=14, Width=200, Height=28, FontSize=14,
                             TabIndex=1)
        self.lblScore = Label(self, Caption='', Left=232, Top=14, Width=230, Height=28,
                              Alignment=1, FontSize=14, TabIndex=2)
        self.lblQuestion = Label(self, Caption='Press Start', Left=16, Top=70, Width=446,
                                 Height=56, Alignment=2, FontSize=28, TabIndex=3)
        self.txtAnswer = TextBox(self, Text='', Left=140, Top=140, Width=200, Height=42,
                                 Alignment=2, FontSize=20, Enabled=False, TabIndex=4)
        self.lblFeedback = Label(self, Caption='', Left=16, Top=196, Width=446, Height=26,
                                 Alignment=2, TabIndex=5)
        self.cmdStart = CommandButton(self, Caption='&Start', Left=180, Top=240, Width=120,
                                      Height=36, TabIndex=6)
        self.lblBest = Label(self, Caption='', Left=16, Top=290, Width=446, Height=24, Alignment=2,
                             TabIndex=7)
        self.tmrClock = Timer(self, Interval=1000, Enabled=False)
    # endregion

    left = 0  # (seconds)
    score = tried = 0
    answer = 0
    rng = random.Random()

    def Form_Load(self):
        self.lblTime.Caption = f"Time: {SECONDS}"
        self.lblScore.Caption = "Score: 0"
        self.show_best()

    def best(self):
        return int(GetSetting(APP, SECTION, "Best", "0") or 0)

    def show_best(self):
        self.lblBest.Caption = f"Best score: {self.best()}"

    def cmdStart_Click(self):
        self.left, self.score, self.tried = SECONDS, 0, 0
        self.lblScore.Caption = "Score: 0"
        self.lblTime.Caption = f"Time: {SECONDS}"
        self.lblFeedback.Caption = ""
        self.txtAnswer.Enabled = True
        self.cmdStart.Enabled = False
        self.tmrClock.Enabled = True
        self.new_question()
        self.txtAnswer.SetFocus()

    def new_question(self):
        """A question from one of the four operations, with whole-number answers."""
        rng = self.rng
        kind = rng.choice("+-×÷")
        if kind == "+":
            a, b = rng.randint(10, 99), rng.randint(10, 99)
            self.answer = a + b
        elif kind == "-":
            a = rng.randint(20, 120)
            b = rng.randint(1, a)
            self.answer = a - b
        elif kind == "×":
            a, b = rng.randint(2, 12), rng.randint(2, 12)
            self.answer = a * b
        else:  # (a division that comes out exactly)
            b, self.answer = rng.randint(2, 12), rng.randint(2, 12)
            a = b * self.answer
        self.lblQuestion.Caption = f"{a} {'−' if kind == '-' else kind} {b} ="
        self.txtAnswer.Text = ""

    def txtAnswer_KeyPress(self, KeyAscii):
        if KeyAscii == 13:  # (Enter)
            self.check()
            return 0
        return KeyAscii

    def check(self):
        typed = self.txtAnswer.Text.strip()
        if not typed.isdigit():
            self.lblFeedback.Caption = "Type a whole number."
            return
        self.tried += 1
        if int(typed) == self.answer:
            self.score += 1
            self.lblFeedback.Caption = "Right!"
        else:
            self.lblFeedback.Caption = f"Not quite: it was {self.answer}."
        self.lblScore.Caption = f"Score: {self.score} of {self.tried}"
        self.new_question()

    def tmrClock_Timer(self):
        self.left -= 1
        self.lblTime.Caption = f"Time: {self.left}"
        if self.left <= 0:
            self.game_over()

    def game_over(self):
        self.tmrClock.Enabled = False
        self.txtAnswer.Enabled = False
        self.cmdStart.Enabled = True
        self.lblQuestion.Caption = "Time's up!"
        if self.score > self.best():
            SaveSetting(APP, SECTION, "Best", str(self.score))
            self.lblFeedback.Caption = f"A new best score: {self.score}!"
        self.show_best()


if __name__ == "__main__":
    run(Form1)
